package main

import (
	"fmt"
	"os"
	"regexp"
	"strconv"
	"strings"
)

type Options struct {
	AcceptedStatusCodes      string
	BufferSize               int
	MaxConnections           int
	MaxConnectionsPerHost    int
	MaxResponseBodySize      int
	Exclude                  []string
	Include                  []string
	FollowRobotsTxt          bool
	FollowSitemapXml         bool
	Headers                  []string
	IgnoreFragments          bool
	MaxRetries               uint
	DNSResolver              string
	Format                   string
	Json                     bool
	ExperimentalVerboseJson  bool
	Junit                    bool
	MaxRedirections          int
	RateLimit                int
	Timeout                  int
	Verbose                  bool
	Proxy                    string
	SkipTLSVerification      bool
	OnePageOnly              bool
	Color                    string
	Help                     bool
	Version                  bool
}

func defaultOptions() Options {
	return Options{
		AcceptedStatusCodes:   "200..300",
		BufferSize:            4096,
		MaxConnections:        512,
		MaxConnectionsPerHost: 512,
		MaxResponseBodySize:   10000000,
		Format:                "text",
		MaxRedirections:       64,
		Timeout:               10,
		MaxRetries:            0,
		Color:                 "auto",
	}
}

type parseError struct {
	msg string
}

func (e *parseError) Error() string { return e.msg }

func run(args []string) error {
	opts := defaultOptions()
	// quick check for --help and --version before parsing?
	// Need to handle exactly as go-flags: --help prints help and exits 0 regardless of other args? According to earlier, --help with extra arg still prints help and exits 0.
	// Similarly --version.
	// Also need to handle -h.

	// We'll implement manual parser that mimics go-flags errors.
	remaining, err := parseArgs(args, &opts)
	if err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		return err
	}
	if opts.Help {
		fmt.Print(helpText)
		return nil
	}
	if opts.Version {
		fmt.Println(version)
		return nil
	}
	if len(remaining) != 1 {
		fmt.Fprintln(os.Stderr, "invalid number of arguments")
		return &parseError{"invalid number of arguments"}
	}
	urlStr := remaining[0]

	// Validate other options
	// regex compile
	for _, pat := range opts.Exclude {
		if _, e := regexp.Compile(pat); e != nil {
			msg := e.Error()
			// go-flags? observed: "error parsing regexp: missing closing ): `(`"
			// The error from regexp.Compile already gives "error parsing regexp: ..."
			fmt.Fprintln(os.Stderr, msg)
			return &parseError{msg}
		}
	}
	for _, pat := range opts.Include {
		if _, e := regexp.Compile(pat); e != nil {
			msg := e.Error()
			fmt.Fprintln(os.Stderr, msg)
			return &parseError{msg}
		}
	}
	// header format
	for _, h := range opts.Headers {
		if !strings.Contains(h, ":") {
			msg := "invalid header format"
			fmt.Fprintln(os.Stderr, msg)
			return &parseError{msg}
		}
		// Also check that header name part non-empty? First part before colon should be non-empty after trim?
		// But earlier "Foo:Bar" accepted, so just check colon.
	}

	// status codes validation
	if _, err := parseStatusCodes(opts.AcceptedStatusCodes); err != nil {
		fmt.Fprintln(os.Stderr, err.Error())
		return err
	}

	// format validation
	format := opts.Format
	if opts.Json {
		format = "json"
	}
	if opts.Junit {
		format = "junit"
	}
	if format != "text" && format != "json" && format != "junit" {
		msg := fmt.Sprintf("Invalid value `%s' for option `--format'. Allowed values are: text, json or junit", opts.Format)
		fmt.Fprintln(os.Stderr, msg)
		return &parseError{msg}
	}
	// color validation
	if opts.Color != "auto" && opts.Color != "always" && opts.Color != "never" {
		msg := fmt.Sprintf("Invalid value `%s' for option `--color'. Allowed values are: auto, always or never", opts.Color)
		fmt.Fprintln(os.Stderr, msg)
		return &parseError{msg}
	}
	// verbose + junit check
	if format == "junit" && opts.Verbose {
		msg := "verbose option not supported for JUnit output"
		fmt.Fprintln(os.Stderr, msg)
		return &parseError{msg}
	}
	// DNS resolver missing port check (early)
	if opts.DNSResolver != "" {
		if !strings.Contains(opts.DNSResolver, ":") {
			// Need to reproduce error: failed to fetch root page: missing port in address
			// Original error for DNS resolver missing port was for root page fetch, not early validation.
			// But we saw --dns-resolver=8.8.8.8 with URL gave failed to fetch root page: missing port in address (and for 8.8.8.8 without port)
			// So we should not error here but later during fetch.
			// However proxy missing port early? Proxy gave failed to fetch root page: address proxy: missing port in address
			// So these errors are at fetch time, not parse time. So we delay.
		}
	}

	// Need to handle max-connections deadlock panic: replicate original behavior exactly.
	// Original code does: newSemaphore(size) where size = maxConnections, etc. If size <0 panic "makechan: size out of range" via make(chan struct{}, size)
	// If size ==0 then deadlock when Request.
	// We need to reproduce same panic/deadlock behavior.
	// We'll create semaphores early to trigger panic if needed, before fetch.
	// If maxConnections <0, panic with stack including semaphore.go:8
	// If maxConnectionsPerHost <0 similarly
	// If both zero, also deadlock at fetch.

	// Let's check max-connections and max-connections-per-host
	if opts.MaxConnections < 0 {
		// panic as original: makechan size out of range
		panic("makechan: size out of range")
	}
	if opts.MaxConnectionsPerHost < 0 {
		panic("makechan: size out of range")
	}
	if opts.MaxConnections == 0 || opts.MaxConnectionsPerHost == 0 {
		// will deadlock later, but we can simulate deadlock after fetch attempt?
		// Original deadlock occurs at fetch time, not immediately. So we need to allow fetch to start then deadlock.
		// We'll handle in crawler: if semaphore size 0, deadlock.
	}

	// Also need to handle proxy parsing error before fetch? Original proxy error: failed to fetch root page: address proxy: missing port in address
	// This error occurs during fetch, not during parse. So we defer to crawl.

	// Then perform crawl
	if err := doCrawl(urlStr, &opts); err != nil {
		return err
	}
	return nil
}

func parseArgs(args []string, opts *Options) ([]string, error) {
	// Define flag metadata for error messages
	// Map long name -> info
	type flagInfo struct {
		short       string // e.g., "-b"
		long        string // e.g., "--buffer-size"
		hasShort    bool
		kind        string // int, uint, string, bool, slice
		allowValues []string // for color, format
	}
	flags := map[string]*flagInfo{
		"accepted-status-codes":       {long: "--accepted-status-codes", kind: "string"},
		"buffer-size":                 {short: "-b", long: "--buffer-size", hasShort: true, kind: "int"},
		"max-connections":             {short: "-c", long: "--max-connections", hasShort: true, kind: "int"},
		"max-connections-per-host":    {long: "--max-connections-per-host", kind: "int"},
		"max-response-body-size":      {long: "--max-response-body-size", kind: "int"},
		"exclude":                     {short: "-e", long: "--exclude", hasShort: true, kind: "slice"},
		"include":                     {short: "-i", long: "--include", hasShort: true, kind: "slice"},
		"follow-robots-txt":           {long: "--follow-robots-txt", kind: "bool"},
		"follow-sitemap-xml":          {long: "--follow-sitemap-xml", kind: "bool"},
		"header":                      {long: "--header", kind: "slice"},
		"ignore-fragments":            {short: "-f", long: "--ignore-fragments", hasShort: true, kind: "bool"},
		"max-retries":                 {long: "--max-retries", kind: "uint"},
		"dns-resolver":                {long: "--dns-resolver", kind: "string"},
		"format":                      {long: "--format", kind: "choice", allowValues: []string{"text", "json", "junit"}},
		"json":                        {long: "--json", kind: "bool"},
		"experimental-verbose-json":   {long: "--experimental-verbose-json", kind: "bool"},
		"junit":                       {long: "--junit", kind: "bool"},
		"max-redirections":            {short: "-r", long: "--max-redirections", hasShort: true, kind: "int"},
		"rate-limit":                  {long: "--rate-limit", kind: "int"},
		"timeout":                     {short: "-t", long: "--timeout", hasShort: true, kind: "int"},
		"verbose":                     {short: "-v", long: "--verbose", hasShort: true, kind: "bool"},
		"proxy":                       {long: "--proxy", kind: "string"},
		"skip-tls-verification":       {long: "--skip-tls-verification", kind: "bool"},
		"one-page-only":               {long: "--one-page-only", kind: "bool"},
		"color":                       {long: "--color", kind: "choice", allowValues: []string{"auto", "always", "never"}},
		"help":                        {short: "-h", long: "--help", hasShort: true, kind: "bool"},
		"version":                     {long: "--version", kind: "bool"},
	}
	// helper to get flagInfo by long name without --
	getInfo := func(name string) *flagInfo {
		if v, ok := flags[name]; ok {
			return v
		}
		return nil
	}
	// helper to get flagInfo by short char
	shortMap := map[string]*flagInfo{}
	for _, info := range flags {
		if info.hasShort {
			shortMap[strings.TrimPrefix(info.short, "-")] = info
		}
	}

	var positional []string
	i := 0
	for i < len(args) {
		arg := args[i]
		if arg == "--" {
			// double dash -> treat remaining as positional?
			// Original gave error for -b -- -> expected argument but got double dash
			// So we treat -- as separator? But earlier -b -- gave error about double dash; so not positional.
			// Let's treat -- as unknown? Actually -b expects value, if next is "--", error as observed.
			// If we just encounter "--" alone without expecting value, maybe just skip?
			// For now, if arg == "--", then treat as positional separator and push rest as positional
			positional = append(positional, args[i+1:]...)
			break
		}
		if strings.HasPrefix(arg, "--") {
			// long flag, may have =value
			eqIdx := strings.Index(arg, "=")
			var name, val string
			var hasVal bool
			if eqIdx != -1 {
				name = arg[2:eqIdx]
				val = arg[eqIdx+1:]
				hasVal = true
			} else {
				name = arg[2:]
			}
			info := getInfo(name)
			if info == nil {
				return nil, &parseError{fmt.Sprintf("unknown flag `%s'", name)}
			}
			if info.kind == "bool" {
				if hasVal {
					// bool flag with =value not expected? go-flags may allow but not needed
					// treat as error? For now, if hasVal, try parse but not in original scope
				}
				setBoolFlag(opts, name, true)
			} else {
				// need value
				if !hasVal {
					// value is next arg
					if i+1 >= len(args) {
						return nil, &parseError{fmt.Sprintf("expected argument for flag `%s'", displayFlag(info))}
					}
					next := args[i+1]
					if strings.HasPrefix(next, "-") {
						// next looks like flag
						return nil, &parseError{fmt.Sprintf("expected argument for flag `%s', but got option `%s'", displayFlag(info), next)}
					}
					val = next
					hasVal = true
					i++
				}
				// Now we have val
				if err := setFlagValue(opts, name, val, info); err != nil {
					return nil, err
				}
			}
		} else if strings.HasPrefix(arg, "-") && arg != "-" {
			// short flag(s) could be combined? Original supports -b 4096 and -b=-1? Actually -b -1 is allowed (single dash with value -1)
			// Need to handle -h, -v, -f, -b, -c, -e, -i, -r, -t
			// Also -b=... maybe?
			// Our earlier tests: -b -1 was considered flag value "-1" not option -1? For buffer-size, -1 was treated as value, not as unknown flag. So short flags that expect value, next arg can be "-1" which starts with "-" but should be considered value if flag expects int.
			// For flags that are bool, like -v, -h, -f, they don't need value.
			// Need to handle shorthands like -b4096? Not seen, but possible.
			// Simpler: handle each arg character by character.

			// Check if arg contains "=" (like -b=-1)
			if strings.Contains(arg, "=") {
				parts := strings.SplitN(arg, "=", 2)
				flagChars := parts[0][1:] // after -
				val := parts[1]
				if len(flagChars) != 1 {
					// e.g., -b=-1 has flagChars "b"
					// treat as unknown?
					return nil, &parseError{fmt.Sprintf("unknown flag `%s'", flagChars)}
				}
				ch := string(flagChars[0])
				info := shortMap[ch]
				if info == nil {
					return nil, &parseError{fmt.Sprintf("unknown flag `%s'", ch)}
				}
				name := strings.TrimPrefix(info.long, "--")
				if info.kind == "bool" {
					setBoolFlag(opts, name, true)
				} else {
					if err := setFlagValue(opts, name, val, info); err != nil {
						return nil, err
					}
				}
			} else {
				// Could be multiple bool flags combined like -vh ? Not tested, but we can support.
				// Or single flag with separate value next arg.
				chars := arg[1:]
				// If length >1 and any flag expects value, then remainder is value?
				// Example: "-b" alone expects value next arg, but "-bv" would be ambiguous.
				// We'll process sequentially.
				handled := false
				for idx, ch := range chars {
					chStr := string(ch)
					info := shortMap[chStr]
					if info == nil {
						return nil, &parseError{fmt.Sprintf("unknown flag `%s'", chStr)}
					}
					name := strings.TrimPrefix(info.long, "--")
					if info.kind == "bool" {
						setBoolFlag(opts, name, true)
					} else {
						// needs value
						var val string
						if idx+1 < len(chars) {
							// remainder of chars is value? e.g., "-b4096"
							val = chars[idx+1:]
							// consume rest
							if err := setFlagValue(opts, name, val, info); err != nil {
								return nil, err
							}
							handled = true
							break
						} else {
							// value next arg
							if i+1 >= len(args) {
								return nil, &parseError{fmt.Sprintf("expected argument for flag `%s'", displayFlag(info))}
							}
							next := args[i+1]
							// If next starts with "-" but could be negative number, allow for int/uint flags?
							// Check if next is option-like: starts with "-" and not a number?
							if strings.HasPrefix(next, "-") {
								// Check if value could be negative number for int flags
								if info.kind == "int" || info.kind == "uint" {
									// try to parse as int, if it's like "-1", allow
									if _, err := strconv.Atoi(next); err != nil {
										// not a number, treat as option
										return nil, &parseError{fmt.Sprintf("expected argument for flag `%s', but got option `%s'", displayFlag(info), next)}
									}
									// else allow as value
								} else {
									// string/choice/slice flags value starting with - should be considered option? But header could be "-foo"? Not needed.
									return nil, &parseError{fmt.Sprintf("expected argument for flag `%s', but got option `%s'", displayFlag(info), next)}
								}
							}
							val = next
							i++
							if err := setFlagValue(opts, name, val, info); err != nil {
								return nil, err
							}
							handled = true
							break
						}
					}
				}
				if !handled {
					// all were bools
				}
			}
		} else {
			// positional
			positional = append(positional, arg)
		}
		i++
	}
	return positional, nil
}

func displayFlag(info *flagInfo) string {
	if info.hasShort {
		return fmt.Sprintf("%s, %s", info.short, info.long)
	}
	return info.long
}

func setBoolFlag(opts *Options, name string, val bool) {
	switch name {
	case "follow-robots-txt":
		opts.FollowRobotsTxt = val
	case "follow-sitemap-xml":
		opts.FollowSitemapXml = val
	case "ignore-fragments":
		opts.IgnoreFragments = val
	case "json":
		opts.Json = val
	case "experimental-verbose-json":
		opts.ExperimentalVerboseJson = val
	case "junit":
		opts.Junit = val
	case "verbose":
		opts.Verbose = val
	case "skip-tls-verification":
		opts.SkipTLSVerification = val
	case "one-page-only":
		opts.OnePageOnly = val
	case "help":
		opts.Help = val
	case "version":
		opts.Version = val
	}
}

func setFlagValue(opts *Options, name, val string, info *flagInfo) error {
	switch name {
	case "accepted-status-codes":
		opts.AcceptedStatusCodes = val
	case "buffer-size":
		v, err := strconv.Atoi(val)
		if err != nil {
			return &parseError{fmt.Sprintf("invalid argument for flag `%s' (expected int): strconv.ParseInt: parsing \"%s\": invalid syntax", displayFlag(info), val)}
		}
		opts.BufferSize = v
	case "max-connections":
		v, err := strconv.Atoi(val)
		if err != nil {
			return &parseError{fmt.Sprintf("invalid argument for flag `%s' (expected int): strconv.ParseInt: parsing \"%s\": invalid syntax", displayFlag(info), val)}
		}
		opts.MaxConnections = v
	case "max-connections-per-host":
		v, err := strconv.Atoi(val)
		if err != nil {
			return &parseError{fmt.Sprintf("invalid argument for flag `%s' (expected int): strconv.ParseInt: parsing \"%s\": invalid syntax", displayFlag(info), val)}
		}
		opts.MaxConnectionsPerHost = v
	case "max-response-body-size":
		v, err := strconv.Atoi(val)
		if err != nil {
			return &parseError{fmt.Sprintf("invalid argument for flag `%s' (expected int): strconv.ParseInt: parsing \"%s\": invalid syntax", displayFlag(info), val)}
		}
		opts.MaxResponseBodySize = v
	case "exclude":
		opts.Exclude = append(opts.Exclude, val)
	case "include":
		opts.Include = append(opts.Include, val)
	case "header":
		opts.Headers = append(opts.Headers, val)
	case "max-retries":
		v, err := strconv.ParseUint(val, 10, 64)
		if err != nil {
			return &parseError{fmt.Sprintf("invalid argument for flag `%s' (expected uint): strconv.ParseUint: parsing \"%s\": invalid syntax", displayFlag(info), val)}
		}
		opts.MaxRetries = uint(v)
	case "dns-resolver":
		opts.DNSResolver = val
	case "format":
		opts.Format = val
	case "max-redirections":
		v, err := strconv.Atoi(val)
		if err != nil {
			return &parseError{fmt.Sprintf("invalid argument for flag `%s' (expected int): strconv.ParseInt: parsing \"%s\": invalid syntax", displayFlag(info), val)}
		}
		opts.MaxRedirections = v
	case "rate-limit":
		v, err := strconv.Atoi(val)
		if err != nil {
			return &parseError{fmt.Sprintf("invalid argument for flag `%s' (expected int): strconv.ParseInt: parsing \"%s\": invalid syntax", displayFlag(info), val)}
		}
		opts.RateLimit = v
	case "timeout":
		v, err := strconv.Atoi(val)
		if err != nil {
			return &parseError{fmt.Sprintf("invalid argument for flag `%s' (expected int): strconv.ParseInt: parsing \"%s\": invalid syntax", displayFlag(info), val)}
		}
		opts.Timeout = v
	case "proxy":
		opts.Proxy = val
	case "color":
		opts.Color = val
	}
	return nil
}

func parseStatusCodes(s string) (map[int]bool, error) {
	// Returns map for quick lookup, also need to detect inclusive logic later.
	// But validation only here; actual use will need ranges.
	if s == "" {
		return nil, &parseError{"invalid status code range: "}
	}
	parts := strings.Split(s, ",")
	for _, part := range parts {
		part = strings.TrimSpace(part)
		if part == "" {
			return nil, &parseError{"invalid status code range: "}
		}
		if strings.Contains(part, "..") {
			// Should contain exactly one ".."
			if strings.Count(part, "..") != 1 {
				return nil, &parseError{fmt.Sprintf("invalid status code range: %s", part)}
			}
			split := strings.Split(part, "..")
			if len(split) != 2 {
				return nil, &parseError{fmt.Sprintf("invalid status code range: %s", part)}
			}
			lowStr := split[0]
			highStr := split[1]
			if lowStr == "" || highStr == "" {
				// Observed error: "invalid status code: " (with space then nothing)
				empty := ""
				if lowStr == "" {
					empty = lowStr
				} else {
					empty = highStr
				}
				_ = empty
				return nil, &parseError{"invalid status code: "}
			}
			if _, err := strconv.Atoi(lowStr); err != nil {
				return nil, &parseError{fmt.Sprintf("invalid status code: %s", lowStr)}
			}
			if _, err := strconv.Atoi(highStr); err != nil {
				return nil, &parseError{fmt.Sprintf("invalid status code: %s", highStr)}
			}
		} else {
			// single
			if _, err := strconv.Atoi(part); err != nil {
				return nil, &parseError{fmt.Sprintf("invalid status code range: %s", part)}
			}
		}
	}
	// also need to build map for actual checking
	m := make(map[int]bool)
	for _, part := range parts {
		if strings.Contains(part, "..") {
			split := strings.Split(part, "..")
			low, _ := strconv.Atoi(split[0])
			high, _ := strconv.Atoi(split[1])
			// exclusive upper: for loop i < high
			// But need to handle low..high where high exclusive? According spec: 200..300 includes 200-299.
			// However our earlier test showed 200..300 does NOT include 300 (needs location). So exclusive.
			for i := low; i < high; i++ {
				m[i] = true
			}
		} else {
			v, _ := strconv.Atoi(part)
			m[v] = true
		}
	}
	return m, nil
}
EOF
cat parser.go
"}

