func parseStatusCodes(s string) (map[int]bool, error) {
	// Returns map for quick lookup, also need to detect inclusive logic later.
	// But validation only here; actual use will need ranges.
	if s == "" {
		return nil, &parseError{"invalid status code range: "}
	}
	parts := strings.Split(s, ",")
	for _, part := range parts {
		part = strings.TrimSpace(part)
		if part == "" {
			return nil, &parseError{"invalid status code range: "}
		}
		if strings.Contains(part, "..") {
			// Should contain exactly one ".."
			if strings.Count(part, "..") != 1 {
				return nil, &parseError{fmt.Sprintf("invalid status code range: %s", part)}
			}
			split := strings.Split(part, "..")
			if len(split) != 2 {
				return nil, &parseError{fmt.Sprintf("invalid status code range: %s", part)}
			}
			lowStr := split[0]
			highStr := split[1]
			if lowStr == "" || highStr == "" {
				// Observed error: "invalid status code: " (with space then nothing)
				empty := ""
				if lowStr == "" {
					empty = lowStr
				} else {
					empty = highStr
				}
				_ = empty
				return nil, &parseError{"invalid status code: "}
			}
			if _, err := strconv.Atoi(lowStr); err != nil {
				return nil, &parseError{fmt.Sprintf("invalid status code: %s", lowStr)}
			}
			if _, err := strconv.Atoi(highStr); err != nil {
				return nil, &parseError{fmt.Sprintf("invalid status code: %s", highStr)}
			}
		} else {
			// single
			if _, err := strconv.Atoi(part); err != nil {
				return nil, &parseError{fmt.Sprintf("invalid status code range: %s", part)}
			}
		}
	}
	// also need to build map for actual checking
	m := make(map[int]bool)
	for _, part := range parts {
		if strings.Contains(part, "..") {
			split := strings.Split(part, "..")
			low, _ := strconv.Atoi(split[0])
			high, _ := strconv.Atoi(split[1])
			// exclusive upper: for loop i < high
			// But need to handle low..high where high exclusive? According spec: 200..300 includes 200-299.
			// However our earlier test showed 200..300 does NOT include 300 (needs location). So exclusive.
			for i := low; i < high; i++ {
				m[i] = true
			}
		} else {
			v, _ := strconv.Atoi(part)
			m[v] = true
		}
	}
	return m, nil
}
