func isRedirect(code int) bool {
	return code == 301 || code == 302 || code == 303 || code == 307 || code == 308 || code == 300
}

func xmlEscape(s string) string {
   var buf bytes.Buffer
   xml.EscapeText(&buf, []byte(s))
