func (s *semaphore) Acquire() {
	s.ch <- struct{}{}
}
func (s *semaphore) Release() {
	<-s.ch
}

// Host throttler pool
type hostThrottlerPool struct {
	sync.Mutex
	m map[string]*semaphore
	n int
}
func newHostThrottlerPool(n int) *hostThrottlerPool {
	if n < 0 {
		panic("makechan: size out of range")
	}
	return &hostThrottlerPool{m: make(map[string]*semaphore), n: n}
}
func (p *hostThrottlerPool) Get(host string) *semaphore {
	p.Lock()
	defer p.Unlock()
	if s, ok := p.m[host]; ok {
		return s
	}
	s := newSemaphore(p.n)
	p.m[host] = s
